sys_transform_script.script:
(function runTransformScript(source, map, log, target /*undefined onStart*/ ) {

    // Set skip to true if serial number, asset tag, 
	// part id or location is empty
	// The onBefore will ignore these rows.
    var gr_is_row = new GlideRecord(source.getTableName());
    gr_is_row.addQuery("sys_import_set", import_set.sys_id);
    gr_is_row.query();
    while (gr_is_row.hasNext()) {
        gr_is_row.next();

        if (gr_is_row.u_serial_number.nil()) {
            gr_is_row.setValue("u_skip", true);
			gr_is_row.setValue("u_skip_reason", "No serial number");
			gr_is_row.update();
        } else if (gr_is_row.u_asset_tag.nil()) {
            gr_is_row.setValue("u_skip", true);
			gr_is_row.setValue("u_skip_reason", "No asset tag");
			gr_is_row.update();
        } else if (gr_is_row.u_part_id.nil()) {
            gr_is_row.setValue("u_skip", true);
			gr_is_row.setValue("u_skip_reason", "No part id");
			gr_is_row.update();
        } else if (gr_is_row.u_location.nil()) {
            gr_is_row.setValue("u_skip", true);
			gr_is_row.setValue("u_skip_reason", "No location");
			gr_is_row.update();
        }
    }

})(source, map, log, target);
